contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint m, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (m)); require(m <= 1000000000000000000000000000000);
        require(am <= m);
        c.SetMinSum(m); if (__ESBMC_reverted()) return;
        c.Deposit{value: m}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.balances(address(this)) == balBefore - am && address(c).balance == ethBefore - am);
    }
    receive() external payable {}
}

