pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 am) internal {
        m = bound(m, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(am <= m);
        try c.SetMinSum(m) {} catch { return; }
        try c.Deposit{value: m}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore - am && address(c).balance == ethBefore - am);
    }

    function testFuzz_run(uint256 m, uint256 am) public {
        _run(m, am);
    }

    receive() external payable {}
}
